// class key → [family, talent profile]
export const TOP_COIN_CLASS_PROFILE: Readonly<Record<string, readonly [string, string]>> = {"Beginner":["beginner","base"],"Journeyman":["beginner","t22"],"Maestro":["beginner","t22"],"Voidwalker":["beginner","t22"],"Warrior":["warrior","base"],"Barbarian":["warrior","base"],"Blood_Berserker":["warrior","base"],"Death_Bringer":["warrior","base"],"Squire":["warrior","base"],"Divine_Knight":["warrior","base"],"Archer":["archer","base"],"Bowman":["archer","base"],"Siege_Breaker":["archer","base"],"Hunter":["archer","base"],"Beast_Master":["archer","base"],"Wind_Walker":["archer","base"],"Mage":["mage","base"],"Shaman":["mage","base"],"Bubonic_Conjuror":["mage","base"],"Arcane_Cultist":["mage","base"],"Wizard":["mage","base"],"Elemental_Sorcerer":["mage","base"],"Royal_Guardian":["warrior","base"]};

// Family used when no class is known (the highest-reaching one).
export const TOP_COIN_DEFAULT_FAMILY = "warrior";

/** The top Coin Multi reference for a class — its family's base merged with its profile. */
export function topCoinFlatForClass(classKey: string | null | undefined): FlatMap {
  const [family, profile] = (classKey && TOP_COIN_CLASS_PROFILE[classKey]) || [TOP_COIN_DEFAULT_FAMILY, "base"];
  const base = TOP_COIN_FAMILY_FLAT[family] ?? TOP_COIN_FAMILY_FLAT[TOP_COIN_DEFAULT_FAMILY];
  const override = TOP_COIN_PROFILE_OVERRIDES[`${family}:${profile}`];
  return override ? { ...base, ...override } : base;
}
